        const G = p.Rc / p.Re, A = G * p.vin / 1000, clipTop = VC + A > 12 ? 1 : 0, clipLow = VC - A < VE + 0.2 ? 1 : 0;
        return { G, Ic, VE, VC, Vce: VC - VE, sat, clipTop, clipLow, clip: clipTop || clipLow ? 1 : 0, g10ok: G >= 9.5 && G <= 10.5 && p.vin >= 300 && !clipTop && !clipLow ? 1 : 0, Icb100: p.beta == 100 ? Ic : 0, b300ok: p.beta == 300 && Ic >= 0.0009 && Ic <= 0.0013 ? 1 : 0 };
