        for (let i = 0; i <= 120; i++) { const x = (40 + 250 * i / 120).toFixed(1), sn = Math.sin(i / 120 * 4 * Math.PI - t * 3); dout += (i ? 'L' : 'M') + x + ' ' + Y(Math.max(floor, Math.min(12, o.VC - A * sn))).toFixed(1); din += (i ? 'L' : 'M') + x + ' ' + (166 - 10 * Math.min(1, p.vin / 500) * sn).toFixed(1); }
        let s = W('M40 22V150H290', 'currentColor', 1.2) + tx(36, Y(12) + 4, '12 V', 'vizsm', 'end') + tx(36, Y(0) + 4, '0', 'vizsm', 'end');
