  const SVG_PMOS = sv(190, `${W('M110 14H260')}${tx(120, 12, '+12 V', 'vizsm')}${P('pmos', 190, 60)}${W('M200 14V30M200 90V120')}<rect x="186" y="120" width="28" height="36" rx="4" fill="var(--surface)" stroke="currentColor" stroke-width="2"/>${tx(200, 142, 'carga', 'vizsm', 'middle')}${W('M200 156V176')}${P('gnd', 200, 176)}${W('M160 52H130V40M130 14V20M130 52V96')}<rect x="120" y="18" width="20" height="24" fill="var(--surface)"/>${P('res', 130, 30, 90).replace('translate(130 30) rotate(90)', 'translate(130 30) rotate(90) scale(.5)')}${dot(130, 52)}${P('npn', 120, 126)}${W('M130 156V176')}${P('gnd', 130, 176)}${W('M50 126H90')}${tx(46, 130, '5 V', 'vizlab', 'end')}${tx(222, 70, 'S al +', 'vizsm')}${tx(222, 84, 'enciende con', 'vizsm')}${tx(222, 98, 'puerta abajo', 'vizsm')}`);
